-- Round two expands breadth across eras and domains. The fields that are
-- derived below are deliberately explicit because the retrieval engine needs
-- comparable structure, not only a longer list of titles.

create temporary table tether_archive_round_two_seeds (
  slug text primary key,
  title text not null,
  summary text not null,
  year_label text not null,
  start_year integer,
  end_year integer,
  domain_slug text not null,
  event_type_slug text not null,
  structural_summary text not null,
  outcome_summary text not null,
  disanalogy_notes text not null,
  time_to_outcome_days integer,
  source_path text not null default '',
  source_quality_score numeric(4,3) not null,
  case_confidence_score numeric(4,3) not null,
  mechanism_slugs text[] not null
) on commit drop;

insert into tether_archive_round_two_seeds values
  ('persian-wars', 'The Persian Wars', 'Greek city states resisted Persian expansion through alliances, naval strategy, and a mobilized civic identity.', '499-449 BC', -499, -449, 'geopolitics', 'strategic-competition', 'A large imperial power tests a fragmented regional system, forcing smaller actors to coordinate around survival.', 'Persian expansion was checked, while Athens and Sparta emerged as competing centers inside the Greek world.', 'The actors and technologies are ancient, but coalition formation under existential pressure remains comparable.', 18250, 'Greco-Persian_Wars', .82, .79, ARRAY['power-transition','rivalry-escalation','institutional-hardening']),
  ('alexander-conquests', 'The Conquests of Alexander', 'A fast-moving challenger broke the existing balance across the eastern Mediterranean and built an empire faster than institutions could consolidate it.', '336-323 BC', -336, -323, 'geopolitics', 'strategic-competition', 'A charismatic challenger converts military momentum into a cross-border power transition before administrative institutions catch up.', 'The empire fragmented after the leaders death, but Hellenistic institutions and cultural exchange endured.', 'Modern power transitions are less dependent on one conqueror and usually unfold through organizations and networks.', 4745, 'Alexander_the_Great', .8, .77, ARRAY['power-transition','frontier-privatization','elite-fragmentation']),
  ('roman-republic-collapse', 'The Fall of the Roman Republic', 'Repeated elite conflict, civil war, and institutional exceptions transformed a republic into imperial rule.', '133-27 BC', -133, -27, 'geopolitics', 'legitimacy-crisis', 'Institutions designed for a smaller political community become vulnerable when wealth, military loyalty, and elite competition scale beyond their rules.', 'The republic ended and imperial government stabilized the center while narrowing the space for republican contestation.', 'Modern constitutional systems have different media, legal, and economic structures, so breakdown may be partial rather than terminal.', 38690, 'Crisis_of_the_Roman_Republic', .86, .83, ARRAY['elite-fragmentation','legitimacy-erosion','rules-reset']),
  ('byzantine-fall', 'The Fall of Constantinople', 'The Byzantine state lost its capital after centuries of fiscal, military, and demographic contraction amid rising regional powers.', '1453', 1453, 1453, 'geopolitics', 'legitimacy-crisis', 'A long-declining center becomes brittle when external pressure converges with reduced resources and internal factionalism.', 'Constantinople fell, while Byzantine administrative and cultural influence continued through successor communities.', 'A single city mattered unusually much to this polity; modern states have more distributed infrastructure.', 365, 'Fall_of_Constantinople', .84, .8, ARRAY['network-fragility','elite-fragmentation','legitimacy-erosion']),
  ('mongol-expansion', 'The Mongol Expansion', 'A highly mobile confederation used organizational innovation and strategic speed to overturn established states across Eurasia.', '1206-1294', 1206, 1294, 'geopolitics', 'strategic-competition', 'A peripheral challenger gains advantage by moving faster than settled institutions can coordinate a response.', 'The empire eventually divided, but trade routes, administrative practices, and political boundaries were transformed.', 'Modern challengers usually scale through capital and technology rather than conquest and tribute.', 32120, 'Mongol_Empire', .8, .77, ARRAY['power-transition','frontier-privatization','network-fragility']),
  ('spanish-armada', 'The Spanish Armada', 'Spain attempted to impose a decisive military settlement on England but failed against logistics, weather, and asymmetric naval tactics.', '1588', 1588, 1588, 'geopolitics', 'strategic-competition', 'A dominant power assumes superior resources will overcome a cheaper, more adaptive defensive system.', 'The invasion failed, English confidence rose, and Spanish strategic dominance began to weaken over time.', 'Contemporary power contests are more economic and informational than amphibious.', 180, 'Spanish_Armada', .8, .77, ARRAY['rivalry-escalation','network-fragility','institutional-hardening']),
  ('american-revolution', 'The American Revolution', 'Colonial resistance turned a dispute over taxation and representation into a war over sovereignty and political legitimacy.', '1765-1783', 1765, 1783, 'geopolitics', 'legitimacy-crisis', 'A governing center treats a representation problem as a compliance problem until local grievance becomes a rival source of authority.', 'Independence was achieved, but institution building and unresolved social hierarchies continued after the war.', 'Modern states have more formal channels for representation, though legitimacy gaps can still become secessionist.', 6570, 'American_Revolution', .88, .84, ARRAY['legitimacy-erosion','rules-reset','elite-fragmentation']),
  ('haitian-revolution', 'The Haitian Revolution', 'Enslaved people overturned a colonial order and defeated multiple foreign interventions while creating a new state.', '1791-1804', 1791, 1804, 'geopolitics', 'legitimacy-crisis', 'An excluded population converts moral contradiction and organized resistance into a revolutionary challenge to a coercive order.', 'Colonial rule ended, but the new state faced isolation, debt, and external pressure that constrained its recovery.', 'The racialized plantation system is historically specific; the parallel is the collapse of a system whose legitimacy contradicts its coercion.', 4745, 'Haitian_Revolution', .88, .84, ARRAY['legitimacy-erosion','elite-fragmentation','rules-reset']),
  ('latin-american-independence', 'Latin American Independence Movements', 'Colonial rule weakened as local elites, popular movements, and foreign shocks combined to produce new republics.', '1808-1833', 1808, 1833, 'geopolitics', 'legitimacy-crisis', 'An empire loses authority at the periphery when local actors gain the means and language to claim sovereignty.', 'Most Spanish American colonies became independent, but postwar fragmentation and elite competition limited regional unity.', 'Decolonization now operates under different international norms and economic interdependence.', 9130, 'Spanish_American_wars_of_independence', .84, .81, ARRAY['legitimacy-erosion','elite-fragmentation','rules-reset']),
  ('german-unification', 'German Unification', 'Prussian leadership used war, diplomacy, and institutional integration to consolidate a new national power.', '1864-1871', 1864, 1871, 'geopolitics', 'strategic-competition', 'A capable challenger uses selective conflict and institutional design to turn a fragmented field into a more powerful bloc.', 'A German empire was created, shifting the European balance and contributing to later rivalry.', 'National unification is less likely to follow one state-led path in a world of existing supranational institutions.', 2555, 'Unification_of_Germany', .83, .8, ARRAY['power-transition','rules-reset','rivalry-escalation']),
  ('italian-unification', 'Italian Unification', 'Diplomacy, popular mobilization, and limited wars brought fragmented Italian states into a national kingdom.', '1815-1871', 1815, 1871, 'geopolitics', 'strategic-competition', 'A fragmented political landscape becomes a power transition when a coalition aligns identity, diplomacy, and military leverage.', 'A unified Italian state emerged, though regional inequality and institutional tensions persisted.', 'Modern state formation is constrained by borders and international organizations that did not exist in the same form.', 20440, 'Italian_unification', .82, .79, ARRAY['power-transition','rules-reset','elite-fragmentation']),
  ('world-war-i', 'World War I', 'Alliance commitments, arms competition, imperial rivalry, and a triggering assassination produced a system-wide war.', '1914-1918', 1914, 1918, 'geopolitics', 'strategic-competition', 'A dense alliance network turns a local shock into a general conflict because actors fear the cost of restraint.', 'Empires fell, borders changed, and the settlement created grievances that shaped the next global crisis.', 'Nuclear deterrence and modern economic ties alter escalation but do not eliminate alliance entrapment.', 1600, 'World_War_I', .92, .89, ARRAY['rivalry-escalation','network-fragility','institutional-hardening']),
  ('treaty-of-versailles', 'The Treaty of Versailles', 'A victorious coalition attempted to redesign the postwar order while balancing punishment, security, and international legitimacy.', '1919', 1919, 1919, 'geopolitics', 'legitimacy-crisis', 'A settlement imposed after systemic conflict becomes unstable when its rules punish a defeated power without creating shared legitimacy.', 'The treaty created a new international framework but left revisionist pressure and economic grievances unresolved.', 'Modern settlements have different enforcement and economic tools, but punitive peace remains a recurring risk.', 365, 'Treaty_of_Versailles', .88, .84, ARRAY['rules-reset','legitimacy-erosion','rivalry-escalation']),
  ('world-war-ii', 'World War II', 'Revisionist powers exploited economic crisis and weak collective security until the conflict became a global war.', '1939-1945', 1939, 1945, 'geopolitics', 'strategic-competition', 'A revisionist challenger tests a divided order whose institutions lack the credibility to deter repeated boundary changes.', 'The Axis powers were defeated and the postwar order was rebuilt around stronger alliances and institutions.', 'The scale of industrial war is exceptional; modern competition may produce coercion without total war.', 2190, 'World_War_II', .94, .91, ARRAY['rivalry-escalation','institutional-hardening','rules-reset']);

insert into tether_archive_round_two_seeds (
  slug, title, summary, year_label, start_year, end_year, domain_slug, event_type_slug,
  structural_summary, outcome_summary, disanalogy_notes, time_to_outcome_days,
  source_quality_score, case_confidence_score, mechanism_slugs
) values
  ('marshall-plan', 'The Marshall Plan', 'The United States used economic reconstruction to stabilize Western Europe and contain the appeal of communist political models.', '1948-1952', 1948, 1952, 'geopolitics', 'strategic-competition', 'A power transition is managed through economic reconstruction that makes a political order more resilient and attractive.', 'Recovery accelerated, Western European alignment deepened, and the Cold War divide became more institutionalized.', 'Modern influence is more distributed across private capital and digital infrastructure than postwar aid was.', 1460, .86, .82, ARRAY['power-transition','commercialization-wave','institutional-hardening']),
  ('berlin-wall-crisis', 'The Berlin Wall Crisis', 'A divided city became the visible boundary of a wider ideological contest and a test of whether either side would escalate.', '1961', 1961, 1961, 'geopolitics', 'strategic-competition', 'A symbolic chokepoint concentrates a global rivalry, making local movement and recognition questions strategic signals.', 'The wall stabilized the immediate crisis while hardening political division for decades.', 'Modern borders are often informational or economic rather than physical walls.', 120, .84, .8, ARRAY['rivalry-escalation','institutional-hardening','network-fragility']),
  ('vietnam-war', 'The Vietnam War', 'A local nationalist conflict became a prolonged proxy war because great powers treated it as a test of ideological credibility.', '1955-1975', 1955, 1975, 'geopolitics', 'strategic-competition', 'External patrons convert a local conflict into a credibility contest where compromise is interpreted as defeat.', 'The United States withdrew, North Vietnam unified the country, and the war reshaped public trust in government.', 'Modern proxy conflicts involve different media and military technologies, but credibility spirals still matter.', 7300, .87, .83, ARRAY['rivalry-escalation','institutional-hardening','legitimacy-erosion']),
  ('detente', 'Cold War Détente', 'The United States and Soviet Union reduced direct confrontation through arms talks and managed competition.', '1969-1979', 1969, 1979, 'geopolitics', 'strategic-competition', 'Two rivals preserve competition while creating rules that reduce the probability of accidental escalation.', 'Arms control and diplomatic channels improved temporarily before rivalry intensified again.', 'Modern rivals have more economic interdependence and more non-state actors in the system.', 3650, .82, .78, ARRAY['institutional-hardening','rivalry-escalation','rules-reset']),
  ('soviet-collapse', 'The Collapse of the Soviet Union', 'Economic stagnation, national movements, and reform weakened a centralized union until its political center dissolved.', '1985-1991', 1985, 1991, 'geopolitics', 'legitimacy-crisis', 'A centralized system attempts reform after losing economic and ideological credibility, but reform exposes the depth of institutional fragmentation.', 'The union dissolved and successor states inherited uneven institutions, borders, and economic dependencies.', 'Modern states are more networked and less ideologically unified, so decline may appear as decentralization rather than collapse.', 2190, .9, .86, ARRAY['legitimacy-erosion','elite-fragmentation','rules-reset']),
  ('yugoslav-wars', 'The Yugoslav Wars', 'Economic crisis, political fragmentation, and nationalist mobilization broke a federal state into violent successor conflicts.', '1991-2001', 1991, 2001, 'geopolitics', 'legitimacy-crisis', 'A federation loses a shared legitimacy story as elites turn identity and territorial fear into competing sources of authority.', 'The federation dissolved, borders hardened, and international intervention produced imperfect settlements.', 'The ethnic and constitutional context is specific; the general signal is elite fragmentation inside a weakening federation.', 3650, .86, .82, ARRAY['elite-fragmentation','legitimacy-erosion','rivalry-escalation']),
  ('tulip-mania', 'Tulip Mania', 'Speculative trading pushed the price of tulip contracts far beyond ordinary use value before confidence reversed.', '1634-1637', 1634, 1637, 'business', 'consumer-trend-swing', 'A status good becomes a speculative asset when social imitation and easy resale replace fundamental valuation.', 'Prices collapsed for many contracts, leaving a durable cultural memory of speculative excess.', 'The market was small and lightly institutionalized compared with modern finance.', 1095, .72, .68, ARRAY['speculative-excess','reputation-contagion','network-fragility']),
  ('south-sea-bubble', 'South Sea Bubble', 'A politically connected company attracted speculative capital through promises of future trade and debt conversion.', '1711-1720', 1711, 1720, 'business', 'consumer-trend-swing', 'A prestigious institution turns political access and optimistic narrative into a self-reinforcing market bubble.', 'The bubble burst, investors suffered losses, and public distrust of financial promotion increased.', 'Modern securities markets have disclosure and regulation, though narrative momentum still outruns cash flow.', 3285, .8, .76, ARRAY['speculative-excess','monopoly-consolidation','reputation-contagion']),
  ('railway-mania', 'Railway Mania', 'Investors funded a wave of railway projects whose infrastructure promise exceeded the capacity of many ventures to earn returns.', '1844-1847', 1844, 1847, 'business', 'platform-transition', 'A transformative infrastructure platform attracts too much capital before demand, governance, and network economics stabilize.', 'Many projects failed or consolidated, while railways became foundational infrastructure.', 'Modern digital platforms scale faster and with less physical capital, but the buildout cycle is comparable.', 1095, .8, .76, ARRAY['speculative-excess','network-fragility','commercialization-wave']),
  ('bretton-woods', 'Bretton Woods System', 'Allied governments designed monetary institutions to stabilize trade and finance after the economic shocks of the interwar period.', '1944-1971', 1944, 1971, 'business', 'regulatory-crackdown', 'A crisis produces a rules reset when states decide that unmanaged financial competition threatens the broader system.', 'The system stabilized postwar growth before pressure on the dollar and capital mobility forced a new monetary regime.', 'The modern system is more market-driven and less centered on one negotiated conference.', 9855, .86, .82, ARRAY['rules-reset','institutional-hardening','network-fragility']),
  ('stagflation-1970s', 'The Stagflation of the 1970s', 'Energy shocks, wage-price dynamics, and weak productivity challenged the assumption that inflation and unemployment could be managed separately.', '1973-1982', 1973, 1982, 'business', 'resource-shock', 'A supply shock exposes limits in the prevailing policy model and forces institutions to choose between competing social priorities.', 'Monetary and fiscal regimes shifted, labor bargaining weakened, and inflation expectations were reset.', 'Energy systems and labor markets have changed, so the policy mix is not directly portable.', 3285, .85, .8, ARRAY['scarcity-shock','rules-reset','labor-realignment']),
  ('black-monday-1987', 'Black Monday', 'A rapid stock-market collapse exposed how automated trading, leverage, and correlated behavior could amplify a financial shock.', '1987', 1987, 1987, 'business', 'resource-shock', 'A liquid market becomes fragile when participants use similar models and exit through the same narrow channels.', 'Markets recovered, but circuit breakers and new risk controls were introduced.', 'Modern markets are faster and more algorithmic, making common-model risk even more relevant.', 90, .84, .8, ARRAY['network-fragility','speculative-excess','rules-reset']),
  ('asian-financial-crisis', 'Asian Financial Crisis', 'Currency pressure, foreign-currency debt, and rapid capital flight destabilized several Asian economies.', '1997-1998', 1997, 1998, 'business', 'resource-shock', 'An apparently successful growth model becomes vulnerable when external capital, currency mismatch, and shared investor narratives reverse together.', 'Currencies fell, recessions spread, and financial regulation and reserve policy were reworked.', 'Capital controls and exchange regimes differ today, but sudden-stop dynamics remain.', 365, .87, .82, ARRAY['network-fragility','scarcity-shock','institutional-hardening']),
  ('russian-financial-crisis-1998', 'Russian Financial Crisis', 'Debt default and currency devaluation followed fiscal weakness, political instability, and loss of investor confidence.', '1998', 1998, 1998, 'business', 'resource-shock', 'A state with weak fiscal credibility loses market access when a confidence shock reveals that short-term financing cannot be rolled over.', 'Default and devaluation caused severe disruption, while later reforms and commodity revenue restored state capacity.', 'The monetary context is specific; sovereign refinancing risk is the reusable mechanism.', 120, .79, .74, ARRAY['scarcity-shock','legitimacy-erosion','rules-reset']),
  ('enron-collapse', 'Enron Collapse', 'Aggressive accounting, complex structures, and executive incentives concealed a deteriorating business until trust collapsed.', '2001', 2001, 2001, 'business', 'scandal-cycle', 'A high-status institution converts complexity and reputation into permission to postpone recognition of failure.', 'The company failed, employees and investors lost heavily, and accounting oversight tightened.', 'Modern firms use different data systems, but incentive-driven opacity remains a recurring risk.', 180, .86, .82, ARRAY['reputation-contagion','speculative-excess','regulatory-backlash']),
  ('lehman-collapse', 'Lehman Brothers Collapse', 'The failure of a highly interconnected investment bank turned housing losses into a global liquidity crisis.', '2008', 2008, 2008, 'business', 'resource-shock', 'A central intermediary appears diversified while its counterparties share hidden exposure and depend on uninterrupted liquidity.', 'The failure accelerated the global financial crisis and produced extraordinary public intervention.', 'The regulatory response changed the system, but non-bank leverage can recreate similar fragility.', 30, .92, .89, ARRAY['network-fragility','scarcity-shock','institutional-hardening']),
  ('eurozone-debt-crisis', 'Eurozone Debt Crisis', 'Sovereign debt stress exposed the tension between a shared currency and nationally controlled fiscal systems.', '2009-2015', 2009, 2015, 'business', 'resource-shock', 'A monetary union faces a legitimacy and liquidity crisis when members share a currency but not a single political risk-bearing center.', 'Emergency lending and institutional reforms preserved the union while deepening political conflict over austerity and solidarity.', 'The euro area is a unique institutional design, but shared-risk disputes recur in federations and alliances.', 2190, .87, .83, ARRAY['network-fragility','rules-reset','legitimacy-erosion']),
  ('ford-assembly-line', 'Ford Assembly Line', 'Moving assembly transformed manufacturing by combining standardization, scale, and a new relationship between labor and capital.', '1913-1920s', 1913, 1929, 'business', 'platform-transition', 'A production process becomes dominant when complementary infrastructure, labor discipline, and consumer demand reinforce one another.', 'Mass production lowered costs and expanded markets while intensifying labor and managerial conflict.', 'Automation and software now shift production with less geographic concentration.', 5840, .85, .81, ARRAY['commercialization-wave','labor-realignment','platform-disintermediation']),
  ('walmart-retail-revolution', 'The Walmart Retail Revolution', 'A logistics and purchasing model scaled discount retail across the United States and reshaped supplier power.', '1962-2000s', 1962, 2009, 'business', 'distribution-shift', 'A retailer gains system power by combining purchasing scale, logistics, and geographic reach into a new gatekeeping position.', 'Retail prices and supply chains changed, while supplier dependence and local-business pressure intensified.', 'Digital marketplaces operate with different assets, but intermediary scale still redistributes bargaining power.', 13790, .82, .78, ARRAY['monopoly-consolidation','distribution-rebundling','commercialization-wave']),
  ('amazon-retail-disruption', 'Amazon Retail Disruption', 'An online marketplace rewired retail around low-friction search, logistics, cloud infrastructure, and platform dependence.', '1994-2020s', 1994, 2020, 'business', 'distribution-shift', 'A new platform reduces transaction friction, then becomes a gatekeeper whose infrastructure and marketplace rules shape competitors.', 'Online retail expanded, traditional retailers adapted, and platform power became a central regulatory concern.', 'The case is ongoing, so the ultimate outcome remains unsettled.', 10950, .86, .8, ARRAY['platform-disintermediation','monopoly-consolidation','distribution-rebundling']),
  ('boeing-737-max-crisis', 'Boeing 737 MAX Crisis', 'A safety failure exposed how commercial pressure, organizational incentives, and regulatory delegation could compound.', '2018-2020', 2018, 2020, 'business', 'scandal-cycle', 'An institution under growth pressure normalizes risk until a visible failure forces a legitimacy and governance reset.', 'The aircraft was grounded, production and oversight changed, and public trust in certification processes weakened.', 'Aviation is unusually safety-critical; the pattern is about incentive drift and institutional correction.', 730, .87, .81, ARRAY['reputation-contagion','institutional-hardening','rules-reset']),
  ('silicon-valley-bank-collapse', 'Silicon Valley Bank Collapse', 'Interest-rate exposure and concentrated deposits produced a fast bank run amplified by digital communication.', '2023', 2023, 2023, 'business', 'resource-shock', 'A specialized institution appears stable until correlated customers and rapid information flows turn liquidity risk into a run.', 'The bank failed and regulators intervened, while deposit and supervision expectations shifted.', 'The speed of digital withdrawals is historically unusual, but the confidence mechanism is old.', 30, .84, .8, ARRAY['network-fragility','scarcity-shock','reputation-contagion']),
  ('argentina-economic-crisis-2001', 'Argentina Economic Crisis', 'Debt pressure, currency constraints, political distrust, and social unrest combined into a broad economic breakdown.', '1998-2002', 1998, 2002, 'business', 'resource-shock', 'A policy regime loses room to maneuver when debt, currency commitments, and public legitimacy fail at the same time.', 'Default, devaluation, and political turnover followed, with long-lasting effects on trust and investment.', 'The currency-board structure is specific; the interaction of fiscal constraint and legitimacy is portable.', 1095, .82, .77, ARRAY['scarcity-shock','legitimacy-erosion','rules-reset']),
  ('afl-nfl-merger', 'AFL-NFL Merger', 'Rival football leagues consolidated after competing for players, audiences, and broadcast economics.', '1966-1970', 1966, 1970, 'sports', 'distribution-shift', 'Two rival organizations discover that competition for scarce talent and shared audiences is less profitable than controlled consolidation.', 'The merger created a dominant league structure and a durable national sports product.', 'Sports leagues have unusually visible rules and shared ownership compared with most media markets.', 1460, .84, .8, ARRAY['rivalry-escalation','distribution-rebundling','commercialization-wave']),
  ('title-ix-sports', 'Title IX and the Expansion of Womens Sports', 'A legal rule reset changed access to education and organized sport, creating new participation and institutional pathways.', '1972-1990s', 1972, 1999, 'sports', 'regulatory-crackdown', 'A formal rule change exposes unequal access and forces institutions to redesign resource allocation.', 'Participation and opportunities expanded, though enforcement and resource parity remained contested.', 'The policy operates inside education and sport, but rule-driven access changes appear across domains.', 8400, .86, .82, ARRAY['rules-reset','labor-realignment','legitimacy-erosion']),
  ('1984-olympics-commercialization', '1984 Olympics Commercialization', 'Los Angeles demonstrated how sponsorship, television, and private management could turn a major sporting event into a profitable global product.', '1984', 1984, 1984, 'sports', 'distribution-shift', 'A public institution adopts commercial packaging and media rights to escape financial fragility.', 'The event turned a profit and established a more commercial model for future Olympics.', 'The event benefited from unusually favorable conditions and cannot be treated as a universal business model.', 45, .82, .77, ARRAY['commercialization-wave','distribution-rebundling','audience-fragmentation']),
  ('wta-professionalization', 'The Professionalization of Womens Tennis', 'Players and organizers built a more coherent professional circuit that expanded visibility, bargaining power, and commercial value.', '1970s-1980s', 1970, 1989, 'sports', 'labor-dispute', 'A previously underpowered labor group creates a market by organizing around shared visibility and collective bargaining leverage.', 'Professional opportunities and audience value expanded, while disputes over pay and governance continued.', 'Sport-specific media economics shape the result, but labor organization remains the useful mechanism.', 7300, .82, .78, ARRAY['labor-realignment','distribution-rebundling','rules-reset']),
  ('1999-womens-world-cup', '1999 Womens World Cup', 'A high-visibility tournament turned womens football into a mass cultural and commercial event in the United States.', '1999', 1999, 1999, 'sports', 'distribution-shift', 'A formerly marginal audience crosses a visibility threshold when a compelling event aligns with media distribution and symbolic identification.', 'Participation and commercial interest increased, although institutional support remained uneven.', 'The effect depended on a specific host market and media moment.', 30, .79, .73, ARRAY['audience-fragmentation','commercialization-wave','distribution-rebundling']),
  ('nba-globalization', 'NBA Globalization', 'The NBA used television, star narratives, and international events to turn a domestic league into a global entertainment platform.', '1980s-2000s', 1980, 2009, 'sports', 'distribution-shift', 'A league expands by packaging talent and narrative for new distribution channels, turning an audience into a transnational network.', 'International fandom, player recruitment, and media revenue grew substantially.', 'The league has an unusually strong centralized brand and should not be generalized to all sports.', 7300, .84, .8, ARRAY['distribution-rebundling','commercialization-wave','audience-fragmentation']),
  ('moneyball-era', 'The Moneyball Era', 'Data-driven player evaluation challenged scouting conventions and changed how baseball teams allocated scarce talent.', '2000s', 2000, 2009, 'sports', 'platform-transition', 'A measurement technology gives an outsider a way to exploit inefficiency in an incumbent decision system.', 'Analytics became mainstream, changing recruitment and strategy across professional sports.', 'The market became more efficient after adoption, reducing the advantage of the original challenger.', 3650, .82, .78, ARRAY['platform-disintermediation','rules-reset','commercialization-wave']),
  ('european-super-league-proposal', 'European Super League Proposal', 'Elite clubs attempted to reorganize football around a closed premium competition and direct control of media value.', '2021', 2021, 2021, 'sports', 'distribution-shift', 'A powerful incumbent coalition tries to bypass a shared governance structure to capture more of the audience and revenue stack.', 'The proposal collapsed under fan, political, and institutional backlash, but commercial pressure persisted.', 'The event is recent and unresolved; it is a live example of distribution conflict rather than a settled precedent.', 14, .82, .76, ARRAY['distribution-rebundling','regulatory-backlash','reputation-contagion']),
  ('ncaa-nil-era', 'The NCAA Name Image and Likeness Shift', 'Legal and regulatory changes weakened restrictions on athlete compensation and altered the economic relationship between players and institutions.', '2021-2024', 2021, 2024, 'sports', 'labor-dispute', 'A labor group gains mobility and public leverage when an old compensation rule loses legal legitimacy.', 'Athlete compensation expanded, while the governance and competitive-balance model remained unsettled.', 'The legal status and final structure are still evolving.', 1095, .81, .75, ARRAY['labor-realignment','rules-reset','commercialization-wave']),
  ('tokyo-olympics-postponement', 'Tokyo Olympics Postponement', 'A global public-health crisis forced a major sporting institution to delay its event and redesign operations.', '2020-2021', 2020, 2021, 'sports', 'resource-shock', 'A tightly scheduled global network becomes fragile when a shared external shock makes continuity unsafe or impossible.', 'The Games were held later under restrictions, with financial and emotional costs across the ecosystem.', 'The pandemic was an exceptional global shock; the reusable pattern is coordinated delay under systemic risk.', 365, .82, .77, ARRAY['network-fragility','rules-reset','institutional-hardening']),
  ('radio-golden-age', 'The Golden Age of Radio', 'Radio became a mass medium by combining cheap receivers, national programming, advertising, and shared attention.', '1920s-1950s', 1920, 1959, 'entertainment', 'platform-transition', 'A new medium becomes socially powerful when adoption, repeatable content, and commercial measurement reinforce one another.', 'Radio reshaped politics, advertising, music, and domestic routines before television displaced its centrality.', 'The medium was more centralized than todays digital ecosystem.', 10950, .84, .8, ARRAY['platform-disintermediation','commercialization-wave','audience-fragmentation']),
  ('sound-film-transition', 'The Transition to Sound Film', 'Synchronized sound disrupted silent-film production, talent, theaters, and international distribution.', '1927-1935', 1927, 1935, 'entertainment', 'platform-transition', 'A technical layer becomes a new standard and devalues incumbent skills, equipment, and distribution practices.', 'Sound cinema became dominant while studios reorganized production and employment.', 'The transition was hardware-led and slower than software platform shifts.', 2920, .84, .8, ARRAY['platform-disintermediation','labor-realignment','rules-reset']),
  ('beatles-british-invasion', 'The British Invasion', 'British music acts crossed into the United States and altered youth culture, radio programming, and the economics of pop stardom.', '1964-1967', 1964, 1967, 'entertainment', 'distribution-shift', 'A cultural challenger crosses an attention boundary and forces incumbents to reorganize around a new taste signal.', 'Pop music became more youth-centered and globally networked.', 'The event was concentrated in a short media window and depended on broadcast gatekeepers.', 1095, .8, .76, ARRAY['audience-fragmentation','distribution-rebundling','nostalgia-revival']),
  ('cable-tv-expansion', 'Cable Television Expansion', 'Cable networks multiplied channels and shifted television from a small number of broadcasters toward specialized audiences.', '1970s-1990s', 1970, 1999, 'entertainment', 'distribution-shift', 'A distribution layer fragments mass attention while creating new niche channels and gatekeepers.', 'Specialized programming and subscription economics expanded, eventually setting up the streaming transition.', 'Cable still depended on physical infrastructure and bundles unlike modern internet distribution.', 10950, .84, .8, ARRAY['audience-fragmentation','distribution-rebundling','commercialization-wave']),
  ('youtube-creator-economy', 'The YouTube Creator Economy', 'Open video distribution let individuals build audiences outside legacy television and created a new platform-mediated labor market.', '2005-2010s', 2005, 2019, 'entertainment', 'distribution-shift', 'A low-cost distribution platform bypasses old gatekeepers, then becomes the new gatekeeper through ranking, monetization, and policy.', 'Creator careers and audience niches expanded while dependence on platform rules increased.', 'The platform remains active and its long-run labor model is unresolved.', 5110, .86, .81, ARRAY['gatekeeper-collapse','platform-disintermediation','audience-fragmentation']),
  ('netflix-streaming-transition', 'Netflix Streaming Transition', 'Subscription streaming shifted home entertainment from scheduled physical rentals toward on-demand platforms and original content.', '2007-2018', 2007, 2018, 'entertainment', 'distribution-shift', 'A new delivery model lowers access friction, then reorganizes production, pricing, and audience measurement around itself.', 'Streaming became central, while studios and distributors rebuilt around competing platforms.', 'The market is still consolidating and may not settle into one dominant gatekeeper.', 4015, .87, .82, ARRAY['platform-disintermediation','distribution-rebundling','audience-fragmentation']),
  ('spotify-streaming', 'Music Streaming Adoption', 'Streaming made music access continuous and searchable while shifting value toward platforms, playlists, and subscription bundles.', '2008-2018', 2008, 2018, 'entertainment', 'distribution-shift', 'A distribution shock removes scarcity at the access layer and creates a new intermediary that controls discovery and monetization.', 'Listening became more abundant, but artists and labels renegotiated bargaining power with platforms.', 'The economics depend on subscription markets and algorithmic discovery.', 3650, .86, .81, ARRAY['platform-disintermediation','distribution-rebundling','gatekeeper-collapse']),
  ('reality-tv-boom', 'Reality Television Boom', 'Low-cost unscripted formats expanded television output and made ordinary participants into repeatable media products.', '1990s-2000s', 1990, 2009, 'entertainment', 'consumer-trend-swing', 'A cost-saving format becomes a cultural engine when audiences accept authenticity as a substitute for conventional production.', 'Reality formats became a durable programming category and changed celebrity pathways.', 'The format is dependent on television schedules and may translate differently to social platforms.', 5110, .78, .73, ARRAY['commercialization-wave','audience-fragmentation','reputation-contagion']),
  ('influencer-economy', 'The Influencer Economy', 'Personal brands, creator platforms, and targeted advertising turned identity and attention into a distributed commercial system.', '2010s', 2010, 2019, 'entertainment', 'platform-transition', 'A distributed audience layer creates new intermediaries who monetize trust, identity, and recommendation.', 'Advertising and commerce shifted toward creators, while authenticity and disclosure became governance problems.', 'The category is still evolving and platform dependence remains high.', 3650, .82, .77, ARRAY['commercialization-wave','platform-disintermediation','reputation-contagion']),
  ('tiktok-attention-shift', 'TikTok Attention Shift', 'Short-form algorithmic video changed discovery by prioritizing recommendation over follower networks and legacy programming.', '2018-2020s', 2018, 2024, 'entertainment', 'distribution-shift', 'A platform changes the ranking mechanism for attention and forces creators, publishers, and competitors to adapt.', 'Short-form video became a dominant discovery format and intensified debates over platform governance.', 'The platform and regulatory outcome remain unsettled.', 2190, .81, .75, ARRAY['audience-fragmentation','platform-disintermediation','distribution-rebundling']),
  ('abolitionist-movement', 'The Abolitionist Movement', 'Organized moral persuasion, political mobilization, and witness challenged slavery as a legitimate institution.', '1780s-1865', 1780, 1865, 'culture', 'legitimacy-crisis', 'A reform movement exposes a contradiction between public ideals and institutional practice until the old order cannot defend itself without revealing the contradiction.', 'Slavery was legally abolished in the United States, though racial inequality and political conflict continued.', 'The legal and racial context is specific; the general pattern is moral delegitimation followed by rules reset.', 31025, .91, .88, ARRAY['legitimacy-erosion','reputation-contagion','rules-reset']),
  ('womens-suffrage', 'The Womens Suffrage Movement', 'Long-term organizing transformed voting rights from a marginal demand into a mainstream legitimacy requirement.', '1848-1920', 1848, 1920, 'culture', 'legitimacy-crisis', 'An excluded group builds durable institutions, reframes exclusion as a legitimacy failure, and converts moral pressure into formal rules.', 'Women gained constitutional voting rights in the United States, while broader equality remained contested.', 'The movement had a long time horizon and uneven inclusion across race and class.', 26280, .9, .86, ARRAY['legitimacy-erosion','rules-reset','labor-realignment']),
  ('beat-generation', 'The Beat Generation', 'A literary and social movement rejected postwar conformity and supplied symbols later adopted by larger countercultures.', '1940s-1950s', 1940, 1959, 'culture', 'cultural-revival', 'A small outsider network creates a vocabulary that later movements use to challenge the dominant cultural order.', 'Beat styles and themes entered mainstream culture while the original subculture retained outsider status.', 'The movement was small and literary compared with later mass media cultures.', 7300, .76, .71, ARRAY['nostalgia-revival','audience-fragmentation','commercialization-wave']),
  ('punk-movement', 'Punk Movement', 'Punk used music, style, and independent distribution to contest the polished commercial culture of the 1970s.', '1970s-1980s', 1974, 1989, 'culture', 'cultural-revival', 'A low-cost outsider network creates symbolic power by rejecting the production and status rules of an established scene.', 'Punk influenced fashion, music, and politics while many symbols were commercialized.', 'The movement had many local scenes and cannot be reduced to one institutional outcome.', 5475, .78, .73, ARRAY['nostalgia-revival','gatekeeper-collapse','commercialization-wave']),
  ('hip-hop-mainstreaming', 'Hip-Hop Mainstreaming', 'A local cultural form developed its own distribution and then reshaped global music, language, fashion, and commerce.', '1970s-1990s', 1973, 1999, 'culture', 'cultural-revival', 'An excluded or peripheral creative network builds alternative institutions before mainstream distribution absorbs and scales the signal.', 'Hip-hop became a dominant global cultural and commercial force while debates over ownership and authenticity persisted.', 'Its origins and internal diversity are too broad for one direct analogy.', 9490, .87, .82, ARRAY['gatekeeper-collapse','commercialization-wave','audience-fragmentation']),
  ('pride-movement', 'The Pride Movement', 'LGBTQ organizing transformed public visibility and legal recognition through community institutions, protest, and cultural change.', '1969-2015', 1969, 2015, 'culture', 'legitimacy-crisis', 'A stigmatized community converts visibility and mutual support into a challenge to legal and social legitimacy.', 'Recognition and rights expanded in many jurisdictions, while backlash and uneven protection persisted.', 'The movement is multi-decade and outcomes vary substantially by jurisdiction.', 16790, .89, .84, ARRAY['legitimacy-erosion','rules-reset','reputation-contagion']),
  ('black-lives-matter', 'Black Lives Matter', 'Networked protest made police violence and racial inequality highly visible, forcing institutions and firms to respond publicly.', '2013-2020s', 2013, 2024, 'culture', 'legitimacy-crisis', 'A decentralized movement uses witness, symbols, and networked attention to expose a legitimacy gap in public institutions.', 'Public debate and policy responses shifted, while institutional change remained uneven and contested.', 'The movement is ongoing and its outcome cannot yet be treated as settled history.', 2920, .83, .77, ARRAY['legitimacy-erosion','reputation-contagion','rules-reset']),
  ('me-too-movement', 'The Me Too Movement', 'Networked testimony changed how workplaces and public institutions evaluated sexual misconduct and power.', '2006-2018', 2006, 2018, 'culture', 'scandal-cycle', 'Individual testimony becomes a collective reputational force that exposes institutional protection of powerful actors.', 'Public accountability increased and many organizations changed policies, though enforcement remains uneven.', 'The movement operates through social media and workplace law in ways earlier scandals did not.', 4380, .84, .79, ARRAY['reputation-contagion','legitimacy-erosion','institutional-hardening']),
  ('climate-strike-movement', 'The Climate Strike Movement', 'Youth-led demonstrations translated climate science and moral urgency into public pressure on governments and firms.', '2018-2020s', 2018, 2024, 'culture', 'legitimacy-crisis', 'A scientific warning becomes a legitimacy test when institutions claim concern but delay costly action.', 'Climate policy and corporate commitments became more visible, but implementation and political conflict continued.', 'The outcome is still open and depends on long-term policy capacity.', 2190, .81, .75, ARRAY['legitimacy-erosion','reputation-contagion','rules-reset']),
  ('decolonization-cultural-politics', 'Decolonization Cultural Politics', 'Postwar movements challenged imperial narratives and sought control over education, language, cultural institutions, and historical memory.', '1945-1980s', 1945, 1989, 'culture', 'legitimacy-crisis', 'A political transition becomes durable only when the old order loses control of the story, institutions, and categories through which authority is understood.', 'States gained independence and cultural institutions were reoriented, though colonial economic structures often persisted.', 'Decolonization varies widely across regions and cannot be captured by a single endpoint.', 14610, .87, .81, ARRAY['legitimacy-erosion','rules-reset','elite-fragmentation']),
  ('cigarette-health-backlash', 'The Cigarette Health Backlash', 'Medical evidence and public advocacy gradually turned smoking from a normalized consumer habit into a regulated health risk.', '1950s-2000s', 1950, 2009, 'lifestyle', 'regulatory-crackdown', 'Scientific evidence challenges a profitable normalized practice, forcing firms and regulators to renegotiate acceptable behavior.', 'Warning labels, restrictions, and public-health campaigns changed consumption and corporate disclosure.', 'The evidence and policy path was unusually long and clear compared with newer health controversies.', 18250, .9, .86, ARRAY['regulatory-backlash','legitimacy-erosion','rules-reset']),
  ('fast-food-globalization', 'Fast Food Globalization', 'Standardized restaurant formats scaled across borders by combining branding, logistics, franchising, and changing consumer routines.', '1950s-2000s', 1950, 2009, 'lifestyle', 'consumer-trend-swing', 'A repeatable commercial format spreads when infrastructure and identity make a once-local behavior portable.', 'Fast food became a global category while provoking health, labor, and cultural backlash.', 'The model depends on physical locations and supply chains unlike digital consumer trends.', 18250, .81, .76, ARRAY['commercialization-wave','distribution-rebundling','network-fragility']),
  ('yoga-mainstream-boom', 'Yoga Mainstream Boom', 'A practice associated with particular spiritual traditions became a mass wellness and consumer category.', '1980s-2010s', 1980, 2019, 'lifestyle', 'consumer-trend-swing', 'A niche practice becomes mainstream when identity, health claims, and commercial infrastructure reinforce each other.', 'Studios, products, and media expanded rapidly, while debates over appropriation and commercialization grew.', 'The cultural origins and commercialization tensions are distinctive.', 10950, .78, .72, ARRAY['commercialization-wave','nostalgia-revival','audience-fragmentation']),
  ('organic-food-boom', 'Organic Food Boom', 'Concern about industrial agriculture and health turned organic products from a niche preference into a major retail category.', '1970s-2000s', 1970, 2009, 'lifestyle', 'consumer-trend-swing', 'A trust-based consumer identity scales when certification and retail distribution make the preference easy to purchase.', 'Organic food entered mainstream retail, while labels and production standards became contested.', 'The category depends on certification systems and price premiums.', 10950, .79, .74, ARRAY['commercialization-wave','rules-reset','reputation-contagion']),
  ('sneaker-culture', 'Sneaker Culture', 'Athletic footwear shifted from equipment to identity, collecting, status, and collaboration.', '1980s-2010s', 1980, 2019, 'lifestyle', 'consumer-trend-swing', 'A functional product becomes a cultural asset when scarcity, celebrity, and community create a status market.', 'Sneakers became a global fashion and resale category, intensifying commercialization and speculation.', 'The product category is unusually visible and brand-driven.', 14610, .8, .75, ARRAY['nostalgia-revival','speculative-excess','commercialization-wave']),
  ('home-fitness-boom', 'Home Fitness Boom', 'Exercise shifted toward home equipment, video instruction, and later digital subscriptions as consumers sought convenience and identity.', '1980s-2020s', 1980, 2024, 'lifestyle', 'consumer-trend-swing', 'A practice becomes scalable when technology converts participation into a repeatable consumer subscription or product.', 'Home fitness expanded in waves, with pandemic adoption accelerating digital platforms and later consolidation.', 'The category remains cyclical and sensitive to novelty and disposable income.', 14610, .79, .73, ARRAY['commercialization-wave','platform-disintermediation','audience-fragmentation']),
  ('secondhand-resale-boom', 'Secondhand Resale Boom', 'Resale platforms and sustainability narratives moved used goods from niche thrift into mainstream commerce and status.', '2010s-2020s', 2010, 2024, 'lifestyle', 'cultural-revival', 'A former marker of constraint becomes a marker of taste when digital discovery and identity reframe older goods.', 'Resale platforms grew, brands entered recommerce, and authenticity became a commercial asset.', 'The long-run environmental impact and market structure remain unsettled.', 3650, .8, .74, ARRAY['nostalgia-revival','platform-disintermediation','distribution-rebundling']),
  ('low-fat-diet-boom', 'Low-Fat Diet Boom', 'Public-health messaging and food marketing made low-fat products a mass consumer category before later evidence complicated the advice.', '1980s-1990s', 1980, 1999, 'lifestyle', 'consumer-trend-swing', 'A simplified expert narrative becomes a mass commercial signal before institutions can observe its second-order effects.', 'Product lines and consumer habits changed, followed by backlash and a more complex nutrition debate.', 'The scientific consensus and product environment have since changed substantially.', 5475, .8, .74, ARRAY['commercialization-wave','reputation-contagion','rules-reset']),
  ('printing-press', 'The Printing Press', 'Movable-type printing lowered the cost of copying ideas and reorganized religion, politics, education, and authority.', '1450-1600', 1450, 1600, 'technology', 'platform-transition', 'A new distribution technology lowers access costs and weakens centralized control over information.', 'Literacy, religious conflict, science, and political mobilization accelerated across Europe.', 'The transition unfolded over centuries and depended on material supply chains.', 54750, .94, .9, ARRAY['platform-disintermediation','gatekeeper-collapse','audience-fragmentation']),
  ('telegraph', 'The Telegraph', 'The electric telegraph compressed communication time and enabled new coordination across markets, governments, and news networks.', '1830s-1870s', 1830, 1879, 'technology', 'platform-transition', 'A communication layer changes coordination speed faster than institutions can update their decision routines.', 'Markets and states became more synchronized, while new information asymmetries and speculation emerged.', 'Modern networks operate at near-zero latency and much larger scale.', 14610, .88, .84, ARRAY['network-fragility','platform-disintermediation','commercialization-wave']),
  ('telephone', 'The Telephone', 'Voice communication moved from local face-to-face networks into a standardized infrastructure with national reach.', '1876-1930s', 1876, 1939, 'technology', 'platform-transition', 'A general-purpose network becomes infrastructure when adoption, standards, and centralized switching reinforce one another.', 'Business and domestic communication changed, creating a regulated utility model.', 'The industry was more vertically integrated and geographically bounded than internet platforms.', 21900, .88, .84, ARRAY['network-fragility','distribution-rebundling','monopoly-consolidation']),
  ('rural-electrification', 'Rural Electrification', 'Public investment extended electric infrastructure beyond profitable urban markets and changed household and agricultural life.', '1930s-1950s', 1930, 1959, 'technology', 'platform-transition', 'A foundational network expands when public institutions absorb early costs that private markets would leave unserved.', 'Productivity and household routines changed, while public infrastructure became a long-term platform for later industries.', 'The policy was state-led and geographically targeted.', 9130, .89, .84, ARRAY['rules-reset','network-fragility','commercialization-wave']),
  ('transistor', 'The Transistor', 'The transistor replaced bulky vacuum tubes and enabled smaller, more reliable, and more scalable electronics.', '1947-1970s', 1947, 1979, 'technology', 'platform-transition', 'A component innovation creates a platform transition by improving cost, reliability, and portability simultaneously.', 'Computing, communications, and consumer electronics scaled into mass markets.', 'The shift was infrastructure-heavy and took decades to diffuse.', 11680, .91, .88, ARRAY['platform-disintermediation','commercialization-wave','frontier-privatization']),
  ('arpanet', 'ARPANET', 'A research network demonstrated packet switching and a distributed model that later supported the public internet.', '1969-1983', 1969, 1983, 'technology', 'platform-transition', 'An experimental network creates a new coordination layer whose most important uses emerge after the original institution releases it outward.', 'The technical model became foundational to the internet and later platform economies.', 'The initial network was small, public, and research-oriented.', 5110, .9, .86, ARRAY['network-fragility','platform-disintermediation','frontier-privatization']),
  ('world-wide-web', 'The World Wide Web', 'A simple open standard made networked information easier to publish, link, and navigate for ordinary users.', '1989-2000s', 1989, 2009, 'technology', 'platform-transition', 'An open protocol lowers participation costs and creates a new information layer that later platforms can monetize.', 'Web publishing, commerce, search, and media expanded rapidly while control shifted toward aggregators.', 'The open protocol and later platform concentration pull in opposite directions.', 7300, .92, .88, ARRAY['platform-disintermediation','gatekeeper-collapse','commercialization-wave']),
  ('cloud-computing', 'Cloud Computing', 'Computing infrastructure moved from owned hardware toward elastic, metered services delivered by large platforms.', '2006-2020s', 2006, 2024, 'technology', 'platform-transition', 'A capability becomes easier to adopt when a platform absorbs capital costs and turns infrastructure into an on-demand service.', 'Software development and business formation accelerated, while dependence on a few infrastructure providers increased.', 'The market is still evolving and concentration may change.', 6570, .87, .81, ARRAY['platform-disintermediation','monopoly-consolidation','frontier-privatization']),
  ('social-network-platform', 'Social Network Platforms', 'Online social networks reorganized identity, communication, news, and advertising around continuously ranked feeds.', '2004-2016', 2004, 2016, 'technology', 'distribution-shift', 'A platform turns social participation into a data-rich distribution system that can scale attention and advertising.', 'Communication and news discovery changed, while misinformation, privacy, and platform governance became central conflicts.', 'The social and political effects remain ongoing and vary by platform.', 4380, .86, .79, ARRAY['audience-fragmentation','reputation-contagion','monopoly-consolidation']),
  ('bitcoin-adoption', 'Bitcoin Adoption', 'A decentralized digital asset challenged conventional assumptions about money, trust, custody, and financial intermediation.', '2009-2020s', 2009, 2024, 'technology', 'platform-transition', 'A technical outsider offers an alternative coordination and ownership model that attracts both ideological and speculative demand.', 'A durable crypto ecosystem formed, alongside volatility, regulation, and repeated speculative cycles.', 'The technology and regulatory status are still unsettled.', 5840, .8, .73, ARRAY['platform-disintermediation','speculative-excess','regulatory-backlash']),
  ('copernican-revolution', 'The Copernican Revolution', 'A new astronomical model displaced an inherited cosmology and changed how institutions understood knowledge and authority.', '1543-1700', 1543, 1700, 'science', 'platform-transition', 'A new explanatory framework gains power when observations accumulate beyond the capacity of the incumbent model.', 'Astronomy and scientific authority were reorganized, contributing to a wider scientific revolution.', 'The transformation was intellectual and slow compared with modern technology cycles.', 56655, .93, .9, ARRAY['rules-reset','gatekeeper-collapse','institutional-hardening']),
  ('darwinian-revolution', 'The Darwinian Revolution', 'Evolution by natural selection challenged inherited accounts of life and changed biology, religion, and public debate.', '1859-1900s', 1859, 1909, 'science', 'platform-transition', 'A theory that explains more observations than the incumbent framework creates a legitimacy conflict beyond its original discipline.', 'Evolution became foundational to biology while cultural and political debates continued.', 'Scientific consensus and social interpretation move at different speeds.', 18250, .92, .88, ARRAY['rules-reset','legitimacy-erosion','institutional-hardening']),
  ('germ-theory', 'The Germ Theory Revolution', 'Microbial explanations of disease changed medicine, public health, sanitation, and state responsibility.', '1860s-1900s', 1860, 1909, 'science', 'platform-transition', 'A new causal model makes previously accepted practices look dangerous and creates demand for institutional redesign.', 'Public-health systems, hygiene, and medical practice changed substantially.', 'The mechanisms were eventually observable and actionable in ways some modern health risks are not.', 14610, .93, .9, ARRAY['rules-reset','network-fragility','institutional-hardening']),
  ('penicillin', 'The Penicillin Breakthrough', 'Mass production of antibiotics transformed infection treatment and created a new pharmaceutical infrastructure.', '1928-1950s', 1928, 1959, 'science', 'platform-transition', 'A discovery becomes a platform when research, manufacturing, and distribution align around a capability with broad downstream effects.', 'Mortality from bacterial infection fell and modern pharmaceutical systems expanded.', 'Resistance and access later created new problems that the original breakthrough did not solve.', 10950, .91, .87, ARRAY['commercialization-wave','frontier-privatization','network-fragility']),
  ('relativity-revolution', 'The Relativity Revolution', 'Relativity displaced classical assumptions about space, time, and gravity and reorganized modern physics.', '1905-1919', 1905, 1919, 'science', 'platform-transition', 'A new framework overturns a successful incumbent model by explaining anomalies and opening a new research frontier.', 'Physics adopted a new conceptual foundation while applications emerged over the following decades.', 'The public and institutional effects were less immediate than platform transitions in commerce.', 5110, .93, .9, ARRAY['rules-reset','frontier-privatization','institutional-hardening']),
  ('continental-drift', 'The Acceptance of Continental Drift', 'Evidence for moving continents eventually overturned a static-earth model and created modern plate tectonics.', '1912-1960s', 1912, 1969, 'science', 'platform-transition', 'A persuasive idea can remain marginal until new instruments and observations make the old model harder to defend.', 'Earth science reorganized around plate tectonics, changing explanations of geology and natural hazards.', 'The delay between insight and acceptance was unusually long.', 18250, .88, .83, ARRAY['rules-reset','institutional-hardening','network-fragility']),
  ('laser-invention', 'The Laser', 'A controlled-light technology moved from theoretical curiosity into communications, medicine, manufacturing, and consumer products.', '1960-1990s', 1960, 1999, 'science', 'platform-transition', 'A general-purpose scientific capability creates value only after complementary industries discover repeatable applications.', 'Laser technologies spread across many sectors and became infrastructure for later systems.', 'The applications were distributed over decades rather than one adoption wave.', 14610, .87, .82, ARRAY['commercialization-wave','frontier-privatization','platform-disintermediation']),
  ('climate-science-consensus', 'The Rise of Climate Science Consensus', 'Accumulating observations and models moved climate change from a specialist concern into a central policy and legitimacy question.', '1970s-2020s', 1970, 2024, 'science', 'legitimacy-crisis', 'A long-running scientific warning becomes politically consequential when institutions cannot reconcile evidence with short-term incentives.', 'Climate policy, investment, and public debate changed, while implementation remains contested.', 'The issue is ongoing and has no single historical endpoint.', 18250, .88, .81, ARRAY['legitimacy-erosion','rules-reset','reputation-contagion']),
  ('standard-model-particle-physics', 'The Standard Model of Particle Physics', 'A set of theories and experiments consolidated a framework for explaining fundamental particles and forces.', '1960s-1980s', 1960, 1989, 'science', 'platform-transition', 'A research field stabilizes around a shared explanatory platform that coordinates instruments, funding, and future questions.', 'The framework became foundational while unresolved anomalies kept new research frontiers open.', 'The institutional cycle is specialized and not a direct consumer-platform analogy.', 10950, .91, .87, ARRAY['rules-reset','institutional-hardening','frontier-privatization']),
  ('cosmic-microwave-background', 'The Discovery of the Cosmic Microwave Background', 'A faint background signal provided powerful evidence for a hot early universe and shifted cosmological consensus.', '1965', 1965, 1965, 'science', 'platform-transition', 'A decisive observation changes a field when it resolves a theoretical dispute and makes one model institutionally dominant.', 'Big Bang cosmology became the standard framework, while new questions emerged about origins and structure.', 'The evidence was unusually decisive compared with contested social sciences.', 90, .9, .86, ARRAY['rules-reset','institutional-hardening','frontier-privatization']);

update tether_archive_round_two_seeds
set source_path = replace(slug, '-', '_')
where source_path = '';

insert into public.historical_cases (
  slug, title, summary, year_label, start_year, end_year, domain_slug, event_type_slug,
  actor_roles, persona_archetypes, preconditions, triggers, structural_summary,
  outcome_summary, disanalogy_notes, time_to_outcome_days, source_quality_score,
  case_confidence_score, metadata
)
select
  seed.slug,
  seed.title,
  seed.summary,
  seed.year_label,
  seed.start_year,
  seed.end_year,
  seed.domain_slug,
  seed.event_type_slug,
  case seed.event_type_slug
    when 'strategic-competition' then '["established power", "rising challenger", "alliance broker"]'::jsonb
    when 'legitimacy-crisis' then '["central authority", "organized challengers", "public witness", "institutional broker"]'::jsonb
    when 'regulatory-crackdown' then '["dominant incumbent", "regulator", "challenger", "public"]'::jsonb
    when 'labor-dispute' then '["employer", "organized workers", "labor broker"]'::jsonb
    when 'platform-transition' then '["legacy incumbent", "new platform", "builders", "users"]'::jsonb
    when 'distribution-shift' then '["legacy gatekeeper", "new distributor", "creators", "audience"]'::jsonb
    when 'cultural-revival' then '["establishment", "cultural movement", "commercial adopter", "public"]'::jsonb
    when 'consumer-trend-swing' then '["specialist movement", "brands", "mass consumers"]'::jsonb
    when 'resource-shock' then '["supplier", "dependent system", "public regulator"]'::jsonb
    when 'scandal-cycle' then '["institution", "public figure", "media audience", "regulator"]'::jsonb
    else '["incumbent", "challenger", "public"]'::jsonb
  end,
  case seed.event_type_slug
    when 'strategic-competition' then '["threatened-king", "anointed-outsider", "court-insider"]'::jsonb
    when 'legitimacy-crisis' then '["threatened-king", "anointed-outsider", "reluctant-messenger", "restorer"]'::jsonb
    when 'regulatory-crackdown' then '["threatened-king", "restorer", "anointed-outsider"]'::jsonb
    when 'labor-dispute' then '["threatened-king", "anointed-outsider", "restorer"]'::jsonb
    when 'platform-transition' then '["threatened-king", "wise-builder", "anointed-outsider"]'::jsonb
    when 'distribution-shift' then '["threatened-king", "wise-builder", "anointed-outsider"]'::jsonb
    when 'cultural-revival' then '["anointed-outsider", "wise-builder", "restorer"]'::jsonb
    when 'consumer-trend-swing' then '["anointed-outsider", "wise-builder", "restorer"]'::jsonb
    when 'resource-shock' then '["threatened-king", "exile-strategist", "restorer"]'::jsonb
    when 'scandal-cycle' then '["threatened-king", "reluctant-messenger", "restorer"]'::jsonb
    else '["threatened-king", "anointed-outsider", "restorer"]'::jsonb
  end,
  jsonb_build_array(
    'The ' || replace(seed.event_type_slug, '-', ' ') || ' pattern has accumulated pressure in the relevant system.',
    seed.summary
  ),
  jsonb_build_array(
    'A visible episode makes the underlying structural pressure impossible to ignore.',
    'Institutions and participants must choose between adaptation, containment, and escalation.'
  ),
  seed.structural_summary,
  seed.outcome_summary,
  seed.disanalogy_notes,
  seed.time_to_outcome_days,
  seed.source_quality_score,
  seed.case_confidence_score,
  jsonb_build_object('seed', 'archive-expansion-v2', 'archive_scope', 'structured-corpus', 'source_pack', 'reference-canon', 'triangulation_status', 'single-reference')
from tether_archive_round_two_seeds as seed
on conflict (slug) do update
set
  title = excluded.title,
  summary = excluded.summary,
  year_label = excluded.year_label,
  start_year = excluded.start_year,
  end_year = excluded.end_year,
  domain_slug = excluded.domain_slug,
  event_type_slug = excluded.event_type_slug,
  actor_roles = excluded.actor_roles,
  persona_archetypes = excluded.persona_archetypes,
  preconditions = excluded.preconditions,
  triggers = excluded.triggers,
  structural_summary = excluded.structural_summary,
  outcome_summary = excluded.outcome_summary,
  disanalogy_notes = excluded.disanalogy_notes,
  time_to_outcome_days = excluded.time_to_outcome_days,
  source_quality_score = excluded.source_quality_score,
  case_confidence_score = excluded.case_confidence_score,
  metadata = coalesce(public.historical_cases.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = timezone('utc', now());

insert into public.historical_case_mechanisms
  (historical_case_id, mechanism_slug, weight, is_primary, evidence_note)
select
  cases.id,
  mechanisms.mechanism_slug,
  case mechanisms.ordinal_position when 1 then 1.000 when 2 then .800 else .650 end,
  mechanisms.ordinal_position = 1,
  'Archive expansion v2: mechanism selected during structured case encoding.'
from tether_archive_round_two_seeds as seed
join public.historical_cases as cases on cases.slug = seed.slug
cross join lateral unnest(seed.mechanism_slugs) with ordinality as mechanisms(mechanism_slug, ordinal_position)
on conflict (historical_case_id, mechanism_slug) do update
set
  weight = excluded.weight,
  is_primary = excluded.is_primary,
  evidence_note = excluded.evidence_note;

insert into public.historical_case_sources
  (historical_case_id, source_type, citation_title, citation_url, publisher, quality_score, notes, metadata)
select
  cases.id,
  'reference',
  seed.title,
  'https://en.wikipedia.org/wiki/' || seed.source_path,
  'Encyclopaedia Britannica / Wikipedia reference',
  seed.source_quality_score,
  'Reference source for archive expansion v2. Treat as a discovery reference until triangulated with an independent source.',
  jsonb_build_object('seed', 'archive-expansion-v2', 'triangulation_status', 'single-reference')
from tether_archive_round_two_seeds as seed
join public.historical_cases as cases on cases.slug = seed.slug
on conflict (historical_case_id, citation_url) where citation_url is not null do update
set
  citation_title = excluded.citation_title,
  publisher = excluded.publisher,
  quality_score = excluded.quality_score,
  notes = excluded.notes,
  metadata = coalesce(public.historical_case_sources.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = timezone('utc', now());

create index if not exists historical_cases_archive_v2_idx
  on public.historical_cases (case_confidence_score desc, source_quality_score desc, start_year);
